from collections import defaultdict, Counter
from fractions import Fraction as F
from pathlib import Path

ROOT = Path('/app')
SCALE = 10000

def read(name):
    with (ROOT / name).open() as f:
        return list(csv.DictReader(f))

def index(name):
    result = {}
    for row in read(name):
        rid = row['run_id']
        if rid in result:
            assert result[rid] == row
